"""Generate Java block, script and character names from the Unicode 16.0 UCD."""

from hashlib import sha256
from pathlib import Path
import sys
import zlib


BLOCKS_SHA = "f3907b395d410f1b97342292ca6bc83dd12eb4b205f2a0c48efdef99e517d7b0"
ALIASES_SHA = "440fd3e5460b9bfe31da67b6f923992e1989d31fe2ed91e091c4b8f8e2620bf9"
UNICODE_DATA_SHA = "ff58e5823bd095166564a006e47d111130813dcf8bf234ef79fa51a870edb48f"


def fields(path, expected_hash):
    data = Path(path).read_bytes()
    if sha256(data).hexdigest() != expected_hash:
        raise SystemExit(f"{path} does not match the expected Unicode 16.0 data.")
    for line in data.decode("utf-8").splitlines():
        record = line.partition("#")[0].strip()
        if record:
            yield [field.strip() for field in record.split(";")]


def block_names(path):
    older_names = {
        "COMBINING DIACRITICAL MARKS FOR SYMBOLS": "COMBINING MARKS FOR SYMBOLS",
        "CYRILLIC SUPPLEMENT": "CYRILLIC SUPPLEMENTARY",
        "GREEK AND COPTIC": "GREEK",
    }
    # This historical name has no assigned scalar range in Java.
    result = {"SURROGATES_AREA": (0xD800, 0xDFFF)}
    canonical_blocks = []
    for bounds, title in fields(path, BLOCKS_SHA):
        first, last = [int(value, 16) for value in bounds.split("..")]
        name = title.upper()
        canonical = older_names.get(name, name)
        canonical_blocks.append((first, last, canonical.replace("-", " ")))
        for alias in {
            name,
            name.replace(" ", ""),
            canonical,
            canonical.replace(" ", ""),
            canonical.replace("-", "_").replace(" ", "_"),
        }:
            result[alias] = (first, last)
    return result, canonical_blocks


def script_names(path):
    # Java's UnicodeScript accepts the ISO abbreviations and enum names.
    excluded = {"Qaac", "Qaai", "Hrkt", "Katakana_Or_Hiragana"}
    return {
        alias.upper(): canonical
        for property_name, short, canonical, *aliases in fields(path, ALIASES_SHA)
        if property_name == "sc"
        for alias in (short, canonical, *aliases)
        if alias not in excluded
    }


def character_names(path, blocks):
    # OpenJDK supplies distinct names for these controls.
    control_names = {
        0x07: "BEL",
        0x80: "PADDING CHARACTER",
        0x81: "HIGH OCTET PRESET",
        0x99: "SINGLE GRAPHIC CHARACTER INTRODUCER",
    }
    names = {}
    unnamed = []
    for hex_code, name, *properties in fields(path, UNICODE_DATA_SHA):
        code = int(hex_code, 16)
        if 0xD800 <= code <= 0xDFFF:
            continue
        if name.endswith(", First>"):
            first = code
        elif name.endswith(", Last>"):
            unnamed.append((first, code))
        else:
            # OpenJDK uses the Unicode 1.0 name field for control characters.
            if name == "<control>":
                name = control_names.get(code, properties[8])
            if name:
                if name in names:
                    raise ValueError(f"Duplicate Java Unicode name: {name}")
                names[name] = code
            else:
                unnamed.append((code, code))
    fallback = [
        (max(first, low), min(last, high), block)
        for first, last in unnamed
        for low, high, block in blocks
        if first <= high and low <= last
    ]
    return names, fallback


def main():
    if len(sys.argv) != 4:
        raise SystemExit(
            "Usage: generate_java_unicode.py Blocks.txt PropertyValueAliases.txt UnicodeData.txt"
        )
    filename = Path(__file__).with_name("src") / "java_unicode.rs"
    blocks, canonical_blocks = block_names(sys.argv[1])
    scripts = script_names(sys.argv[2])
    names, unnamed = character_names(sys.argv[3], canonical_blocks)
    records = "".join(f"{name};{code:X}\n" for name, code in sorted(names.items()))
    filename.with_name("java_character_names.z").write_bytes(zlib.compress(records.encode("ascii"), 9))
    with filename.open("w", encoding="utf-8", newline="\n") as output:
        output.write(
            "// Generated by generate_java_unicode.py from the Unicode 16.0 UCD.\n"
            "// See ../LICENSE-UNICODE for the Unicode data license.\n\n"
            "/// Resolve a Java Unicode block name to its inclusive code-point bounds.\n"
            "pub fn java_unicode_block(name: &str) -> Option<(u32, u32)> {\n"
            "    let key = name.to_uppercase();\n"
            "    let index = BLOCK_NAMES\n"
            "        .binary_search_by_key(&key.as_str(), |&(name, _)| name)\n"
            "        .ok()?;\n"
            "    Some(BLOCK_NAMES[index].1)\n"
            "}\n\n"
            "/// Block name used by Java for an assigned scalar without a Unicode name.\n"
            "pub fn java_unnamed_block(code: u32) -> Option<&'static str> {\n"
            "    let index = UNNAMED_BLOCKS.partition_point(|&(_, last, _)| last < code);\n"
            "    let &(first, _, name) = UNNAMED_BLOCKS.get(index)?;\n"
            "    (first <= code).then_some(name)\n"
            "}\n\n"
            "/// Resolve a Java script name or abbreviation to a Unicode script name.\n"
            "pub fn java_unicode_script(name: &str) -> Option<&'static str> {\n"
            "    let key = name.to_uppercase();\n"
            "    let index = SCRIPT_NAMES\n"
            "        .binary_search_by_key(&key.as_str(), |&(name, _)| name)\n"
            "        .ok()?;\n"
            "    Some(SCRIPT_NAMES[index].1)\n"
            "}\n\n"
            "#[rustfmt::skip]\n"
            "const BLOCK_NAMES: &[(&str, (u32, u32))] = &[\n"
        )
        for name, (first, last) in sorted(blocks.items()):
            output.write(f'    ("{name}", (0x{first:X}, 0x{last:X})),\n')
        output.write("];\n\nconst SCRIPT_NAMES: &[(&str, &str)] = &[\n")
        for name, canonical in sorted(scripts.items()):
            output.write(f'    ("{name}", "{canonical}"),\n')
        output.write("];\n\nconst UNNAMED_BLOCKS: &[(u32, u32, &str)] = &[\n")
        for first, last, block in unnamed:
            output.write(f'    (0x{first:X}, 0x{last:X}, "{block}"),\n')
        output.write("];\n")


if __name__ == "__main__":
    main()
